-- AquaTrace synthetic schema (SQLite)
-- All data generated by seed.py is SYNTHETIC. Not real utility data.

PRAGMA foreign_keys = ON;

DROP TABLE IF EXISTS case_actions;
DROP TABLE IF EXISTS cases;
DROP TABLE IF EXISTS complaints;
DROP TABLE IF EXISTS lab_tests;
DROP TABLE IF EXISTS readings;
DROP TABLE IF EXISTS sensors;
DROP TABLE IF EXISTS maintenance_checks;
DROP TABLE IF EXISTS scenarios;
DROP TABLE IF EXISTS pipes;
DROP TABLE IF EXISTS nodes;
DROP TABLE IF EXISTS meta;

-- Water network graph. parent_id makes the distribution network a tree,
-- which is what makes "walk upstream + lowest common ancestor" cheap and explainable.
CREATE TABLE nodes (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    type        TEXT NOT NULL CHECK (type IN
                  ('source','treatment_plant','reservoir','pump','junction','zone','building')),
    lat         REAL,
    lon         REAL,
    zone_id     TEXT,
    parent_id   TEXT REFERENCES nodes(id)
);

CREATE TABLE pipes (
    id           TEXT PRIMARY KEY,
    from_node    TEXT NOT NULL REFERENCES nodes(id),
    to_node      TEXT NOT NULL REFERENCES nodes(id),
    length_m     REAL NOT NULL,
    diameter_mm  INTEGER NOT NULL,
    material     TEXT NOT NULL,
    install_year INTEGER NOT NULL
);
CREATE INDEX idx_pipes_to ON pipes(to_node);

CREATE TABLE sensors (
    id            TEXT PRIMARY KEY,
    node_id       TEXT NOT NULL REFERENCES nodes(id),
    type          TEXT NOT NULL DEFAULT 'multi',
    installed_year INTEGER
);

CREATE TABLE readings (
    sensor_id            TEXT NOT NULL REFERENCES sensors(id),
    timestamp            TEXT NOT NULL,
    ph                   REAL NOT NULL,
    turbidity_ntu        REAL NOT NULL,
    tds_mgl              REAL NOT NULL,
    residual_chlorine_mgl REAL NOT NULL,
    PRIMARY KEY (sensor_id, timestamp)
);
CREATE INDEX idx_readings_ts ON readings(timestamp);

CREATE TABLE lab_tests (
    id             TEXT PRIMARY KEY,
    node_id        TEXT NOT NULL REFERENCES nodes(id),
    date           TEXT NOT NULL,
    total_coliform TEXT NOT NULL,   -- 'absent' | 'present'
    e_coli         TEXT NOT NULL,   -- 'absent' | 'present'
    notes          TEXT
);

CREATE TABLE complaints (
    id                 TEXT PRIMARY KEY,
    timestamp          TEXT NOT NULL,
    building_node_id   TEXT NOT NULL REFERENCES nodes(id),
    category           TEXT NOT NULL,
    text               TEXT,
    status             TEXT NOT NULL DEFAULT 'NEW',
    suggested_category TEXT,
    extracted_fields   TEXT           -- JSON string, filled by extraction step
);
CREATE INDEX idx_complaints_ts ON complaints(timestamp);

CREATE TABLE cases (
    id          TEXT PRIMARY KEY,
    node_id     TEXT NOT NULL REFERENCES nodes(id),
    scope       TEXT NOT NULL CHECK (scope IN ('MUNICIPAL','BUILDING_SIDE','UNDETERMINED')),
    status      TEXT NOT NULL CHECK (status IN ('Open','Investigating','Action Taken','Resolved')),
    severity    TEXT NOT NULL CHECK (severity IN ('Low','Medium','High')),
    title       TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL,
    rule_fired  TEXT,
    evidence_json TEXT
);

CREATE TABLE case_actions (
    id        TEXT PRIMARY KEY,
    case_id   TEXT NOT NULL REFERENCES cases(id),
    timestamp TEXT NOT NULL,
    actor     TEXT NOT NULL,
    role      TEXT NOT NULL,
    action    TEXT NOT NULL,
    note      TEXT
);
CREATE INDEX idx_actions_case ON case_actions(case_id);

CREATE TABLE maintenance_checks (
    id         TEXT PRIMARY KEY,
    node_id    TEXT NOT NULL REFERENCES nodes(id),
    date       TEXT NOT NULL,
    check_type TEXT NOT NULL,
    result     TEXT NOT NULL,
    notes      TEXT
);

-- Documents the planted demo scenarios so the demo never depends on luck.
CREATE TABLE scenarios (
    id          TEXT PRIMARY KEY,
    title       TEXT NOT NULL,
    description TEXT NOT NULL,
    node_id     TEXT,
    starts_at   TEXT,
    ends_at     TEXT
);

CREATE TABLE meta (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
